360   *
   361   * After allowing server to connect to us from data port, this function
   362   * checks both data connection for connection establishment and ctrl
   363   * connection for a negative response regarding a failure in connecting
   364   *
   365   */
   366  static CURLcode ReceivedServerConnect(struct connectdata *conn, bool *received)
   367  {
   368    struct Curl_easy *data = conn->data;
   369    curl_socket_t ctrl_sock = conn->sock[FIRSTSOCKET];
   370    curl_socket_t data_sock = conn->sock[SECONDARYSOCKET];
   371    struct ftp_conn *ftpc = &conn->proto.ftpc;
   372    struct pingpong *pp = &ftpc->pp;
   373    int result;
   374    timediff_t timeout_ms;
   375    ssize_t nread;
   376    int ftpcode;
   377
   378    *received = FALSE;
   379
   380    timeout_ms = ftp_timeleft_accept(data);
   381    infof(data, "Checking for server connect\n");
   382    if(timeout_ms < 0) {
   383      /* if a timeout was already reached, bail out */
   384      failf(data, "Accept timeout occurred while waiting server connect");
   385      return CURLE_FTP_ACCEPT_TIMEOUT;
   386    }
   387
   388    /* First check whether there is a cached response from server */
   389    if(pp->cache_size && pp->cache && pp->cache[0] > '3') {
   390      /* Data connection could not be established, let's return */
   391      infof(data, "There is negative response in cache while serv connect\n");
   392      (void)Curl_GetFTPResponse(&nread, conn, &ftpcode);
   393      return CURLE_FTP_ACCEPT_FAILED;
   394    }
   395
   396    result = Curl_socket_check(ctrl_sock, data_sock, CURL_SOCKET_BAD, 0);
   397
   398    /* see if the connection request is already here */
   399    switch(result) {
   400    case -1: /* error */
   401      /* let's die here */
   402      failf(data, "Error while waiting for server connect");
   403      return CURLE_FTP_ACCEPT_FAILED;
   404    case 0:  /* Server connect is not received yet */
   405      break; /* loop */
   406    default:
   407
   408      if(result & CURL_CSELECT_IN2) {
   409        infof(data, "Ready to accept data connection from server\n");
   410        *received = TRUE;
   411      }
   412      else if(result & CURL_CSELECT_IN) {
   413        infof(data, "Ctrl conn has data while waiting for data conn\n");
   414        (void)Curl_GetFTPResponse(&nread, conn, &ftpcode);
   415
   416        if(ftpcode/100 > 3)
   417          return CURLE_FTP_ACCEPT_FAILED;
   418
   419        return CURLE_WEIRD_SERVER_REPLY;
   420      }
   421
   422      break;
   423    } /* switch() */
   424
   425    return CURLE_OK;
   426  }
