   429  /***********************************************************************
   430   *
   431   * InitiateTransfer()
   432   *
   433   * After connection from server is accepted this function is called to
   434   * setup transfer parameters and initiate the data transfer.
   435   *
   436   */
   437  static CURLcode InitiateTransfer(struct connectdata *conn)
   438  {
   439    struct Curl_easy *data = conn->data;
   440    CURLcode result = CURLE_OK;
   441
   442    if(conn->bits.ftp_use_data_ssl) {
   443      /* since we only have a plaintext TCP connection here, we must now
   444       * do the TLS stuff */
   445      infof(data, "Doing the SSL/TLS handshake on the data stream\n");
   446      result = Curl_ssl_connect(conn, SECONDARYSOCKET);
   447      if(result)
   448        return result;
   449    }
   450
   451    if(conn->proto.ftpc.state_saved == FTP_STOR) {
   452      /* When we know we're uploading a specified file, we can get the file
   453         size prior to the actual upload. */
   454      Curl_pgrsSetUploadSize(data, data->state.infilesize);
   455
   456      /* set the SO_SNDBUF for the secondary socket for those who need it */
   457      Curl_sndbufset(conn->sock[SECONDARYSOCKET]);
   458
   459      Curl_setup_transfer(data, -1, -1, FALSE, SECONDARYSOCKET);
   460    }
   461    else {
   462      /* FTP download: */
   463      Curl_setup_transfer(data, SECONDARYSOCKET,
   464                          conn->proto.ftpc.retr_size_saved, FALSE, -1);
   465    }
   466
   467    conn->proto.ftpc.pp.pending_resp = TRUE; /* expect server response */
   468    state(conn, FTP_STOP);
   469
   470    return CURLE_OK;
